#!/usr/bin/env node
// Generated by AI Office. Managed file.
// Standalone, local metadata observer. It never reads a transcript or emits a
// Claude hook response. See https://code.claude.com/docs/en/hooks.
import { mkdir, lstat, writeFile, rename, unlink } from 'node:fs/promises';
import { execFileSync } from 'node:child_process';
import { randomUUID } from 'node:crypto';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const EVENTS = new Set(['SessionStart', 'UserPromptSubmit', 'PreToolUse', 'PostToolUse', 'PostToolUseFailure', 'Notification', 'Stop', 'StopFailure', 'SessionEnd', 'SubagentStart', 'SubagentStop']);
const MAX_INPUT_BYTES = 1024 * 1024;
const inbox = path.join(path.dirname(fileURLToPath(import.meta.url)), 'events');

function identifier(value, limit = 180) {
  return typeof value === 'string' && value.length <= limit && /^[a-zA-Z0-9_.:@-]+$/.test(value) ? value : undefined;
}

function cleanCwd(value) {
  return typeof value === 'string' && value.length <= 2048 && !/[\x00-\x1f\x7f]/.test(value) && path.isAbsolute(value) ? path.normalize(value) : undefined;
}

// A shell can sit between the observer and Claude. Record only an ancestor whose
// executable is verifiably Claude, never the observer's short-lived parent PID.
// No command arguments or environment values are inspected or persisted.
function claudeAncestorPid() {
  if (process.platform === 'win32') return undefined;
  let current = process.ppid;
  for (let depth = 0; depth < 8 && current > 1; depth++) {
    let line;
    try {
      // macOS comm truncates long executable paths, even with -ww; ucomm is
      // the executable name. Linux comm already provides that name.
      line = execFileSync('/bin/ps', ['-p', String(current), '-o', 'ppid=', '-o', process.platform === 'darwin' ? 'ucomm=' : 'comm='], { encoding: 'utf8', timeout: 50, maxBuffer: 4096, stdio: ['ignore', 'pipe', 'ignore'] }).trim();
    } catch { return undefined; }
    const match = line.match(/^(\d+)\s+(.+)$/);
    if (!match) return undefined;
    const executable = path.basename(match[2].replace(/ \(deleted\)$/, ''));
    if (/^claude(?:-code)?$/.test(executable)) return current;
    const parent = Number(match[1]);
    if (!Number.isSafeInteger(parent) || parent === current) return undefined;
    current = parent;
  }
  return undefined;
}

function readInput() {
  return new Promise((resolve) => {
    let bytes = 0;
    const chunks = [];
    process.stdin.on('data', chunk => {
      bytes += chunk.length;
      if (bytes > MAX_INPUT_BYTES) process.exit(0);
      chunks.push(chunk);
    });
    process.stdin.on('error', () => resolve(null));
    process.stdin.on('end', () => {
      try { resolve(JSON.parse(Buffer.concat(chunks).toString('utf8'))); }
      catch { resolve(null); }
    });
  });
}

async function main() {
  const raw = await readInput();
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return;
  const sessionId = identifier(raw.session_id);
  if (!EVENTS.has(raw.hook_event_name) || !sessionId) return;
  // Whitelist fields. In particular: prompt, transcript paths, command, tool
  // arguments/results, notifications' message text, and model output are dropped.
  const tool = identifier(raw.tool_name);
  const metadata = {
    event: raw.hook_event_name,
    sessionId,
    agentId: identifier(raw.agent_id),
    agentType: identifier(raw.agent_type),
    cwd: cleanCwd(raw.cwd),
    tool,
    skill: tool === 'Skill' ? identifier(raw.tool_input?.skill) : undefined,
    notificationType: raw.hook_event_name === 'Notification' ? identifier(raw.notification_type, 80) : undefined,
    timestamp: new Date().toISOString(),
    pid: claudeAncestorPid(),
  };
  await mkdir(inbox, { recursive: true, mode: 0o700 });
  const directory = await lstat(inbox);
  if (!directory.isDirectory() || directory.isSymbolicLink()) return;
  const id = `${Date.now()}-${randomUUID()}`;
  const temporary = path.join(inbox, `.${id}.tmp`);
  try {
    await writeFile(temporary, `${JSON.stringify(metadata)}\n`, { flag: 'wx', mode: 0o600 });
    await rename(temporary, path.join(inbox, `${id}.json`));
  } finally {
    await unlink(temporary).catch(() => {});
  }
}

// Observation must never block, fail, or add text to the user's Claude session.
process.on('uncaughtException', () => process.exit(0));
process.on('unhandledRejection', () => process.exit(0));
const deadline = setTimeout(() => process.exit(0), 900);
main().catch(() => {}).finally(() => {
  clearTimeout(deadline);
  process.exit(0);
});
